<script setup lang="ts">
import type {AttachmentPresentation} from '../../domain/session-ui/types'
import { sessionUi as ui, launchController as c } from '../../stores/session-ui'
function hasFile(a:AttachmentPresentation){return a.file instanceof Blob}
function summary(a:AttachmentPresentation) {const kinds:Record<string,string>={image:'图片',video:'视频',audio:'音频',file:'文件'}; const text=`[附件${a.number}] · ${kinds[a.kind]} · ${c.value!.formatSize(a.file?.size ?? a.uploaded?.size ?? 0)}`;return a.status==='uploading'?`${text} · ${a.progress || 0}%`:a.status==='queued'?`${text} · 等待上传`:a.status==='failed'?`${text} · ${a.error || '上传失败'}`:text}
</script>
<template><div v-for="a in ui.bugAttachments" :key="a.id" :class="`draft-card ${a.status || ''}`" :data-draft-id="a.id" :title="`点击插入 [附件${a.number}]`" @click="c?.bugInsert(a.number)"><span class="draft-thumb"><img v-if="a.kind==='image' && a.preview" :src="a.preview" alt=""><template v-else>{{c?.kindIcon(a.kind)}}</template></span><span class="draft-info"><b>{{a.uploaded?.name || a.file?.name || 'attachment'}}</b><small>{{summary(a)}}</small><button v-if="a.status==='failed' && hasFile(a)" type="button" class="draft-retry" title="重新上传" :disabled="ui.bugSending" @click.stop="c?.bugRetry(a.raw)">重试</button></span><button type="button" class="draft-remove" :title="a.cancelUpload?'取消上传':'移除附件'" :aria-label="a.cancelUpload?'取消上传':'移除附件'" :disabled="ui.bugSending && !a.cancelUpload" @click.stop="c?.bugRemove(a.raw)">×</button></div><div v-if="ui.bugStorageError" class="draft-save-error" role="alert">{{ui.bugStorageError}}</div></template>
